CREATE TRIGGER [dbo].[vntTxn_ITrig] ON dbo.vntTxn FOR INSERT AS  /*   * PREVENT NULL VALUES IN 'vntEstado'   */  IF (SELECT Count(*)
FROM inserted
WHERE vntEstado IS NULL) > 0      BEGIN          --RAISERROR 44444 'Field ''vntEstado'' cannot contain a null value.'    RAISERROR('Field ''vntEstado'' cannot contain a null value.', 16, 1)          ROLLBACK TRANSACTION      END  ELSE   /*   * VALIDATION RULE FOR FIELD 'vntEstado'   */  IF (SELECT Count(*) FROM inserted WHERE NOT (vntEstado='A' Or vntEstado='R' Or vntEstado='X')) > 0      BEGIN          RAISERROR(778543, 16, 1)          ROLLBACK TRANSACTION      END  ELSE   /*   * VALIDATION RULE FOR FIELD 'vntExportadoAlFiscal'   */  IF (SELECT Count(*) FROM inserted WHERE NOT (vntExportadoAlFiscal='S' Or vntExportadoAlFiscal='N')) > 0      BEGIN          RAISERROR(778544, 16, 1)          ROLLBACK TRANSACTION      END  /*   * PREVENT INSERTS IF NO MATCHING KEY IN 'gntMoneda'   */  IF (SELECT COUNT(*) FROM inserted) !=     (SELECT COUNT(*) FROM gntMoneda, inserted WHERE (gntMoneda.monId = inserted.monId))      BEGIN          RAISERROR(779087, 16, 1)          ROLLBACK TRANSACTION      END  /*   * PREVENT INSERTS IF NO MATCHING KEY IN 'gntPuntoVenta'   */  IF (SELECT COUNT(*) FROM inserted) !=     (SELECT COUNT(*) FROM gntPuntoVenta, inserted WHERE (gntPuntoVenta.pveId = inserted.pveId))      BEGIN          RAISERROR(779137, 16, 1)          ROLLBACK TRANSACTION      END  /*   * PREVENT INSERTS IF NO MATCHING KEY IN 'gntTipoTxn'   */  IF (SELECT COUNT(*) FROM inserted) !=     (SELECT COUNT(*) FROM gntTipoTxn, inserted WHERE (gntTipoTxn.ttxId = inserted.ttxId))      BEGIN          RAISERROR(779257, 16, 1)          ROLLBACK TRANSACTION      END  